export type TransactionType = 'INCOME' | 'EXPENSE' | 'PROSPECT_INCOME' | 'PROSPECT_EXPENSE';

export type ExpenseCategory = 'Urgente' | 'Importante' | 'Lazer' | 'Desnecessário' | 'Fixo';

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: ExpenseCategory | 'Receita' | 'Prospecção';
  date: string; // ISO format
}

export interface FinancialStats {
  onHand: number;
  projectedTotal: number;
  monthlyExpenses: number;
  monthlyIncome: number;
}

import { Transaction } from './types';

export const formatCurrency = (value: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
};

export const formatDate = (dateString: string) => {
  return new Date(dateString).toLocaleDateString('pt-BR');
};

export const calculateFinances = (transactions: Transaction[]) => {
  let onHand = 0;
  let projectedIncome = 0;
  let projectedExpense = 0;
  let currentMonthIncome = 0;
  let currentMonthExpense = 0;

  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  transactions.forEach((t) => {
    const tDate = new Date(t.date);
    const isCurrentMonth = tDate.getMonth() === currentMonth && tDate.getFullYear() === currentYear;

    if (t.type === 'INCOME') {
      onHand += t.amount;
      if (isCurrentMonth) currentMonthIncome += t.amount;
    } else if (t.type === 'EXPENSE') {
      onHand -= t.amount;
      if (isCurrentMonth) currentMonthExpense += t.amount;
    } else if (t.type === 'PROSPECT_INCOME') {
      projectedIncome += t.amount;
    } else if (t.type === 'PROSPECT_EXPENSE') {
      projectedExpense += t.amount;
    }
  });

  return {
    onHand,
    projectedTotal: onHand + projectedIncome - projectedExpense,
    monthlyIncome: currentMonthIncome,
    monthlyExpenses: currentMonthExpense
  };
};

export const getDaysInMonth = (year: number, month: number) => {
  return new Date(year, month + 1, 0).getDate();
};

export const getFirstDayOfMonth = (year: number, month: number) => {
  return new Date(year, month, 1).getDay();
};

