import React, { useState } from 'react';
import { TransactionType, ExpenseCategory, Transaction } from '../types';

interface TransactionFormProps {
  onAdd: (transaction: Transaction) => void;
  onClose: () => void;
}

export const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, onClose }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<TransactionType>('EXPENSE');
  const [category, setCategory] = useState<ExpenseCategory>('Importante');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const newTransaction: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      description,
      amount: parseFloat(amount),
      type,
      category: (type === 'INCOME' || type === 'PROSPECT_INCOME') ? (type === 'INCOME' ? 'Receita' : 'Prospecção') : category,
      date,
    };

    onAdd(newTransaction);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl animate-in fade-in zoom-in duration-300">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-slate-800">Nova Movimentação</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <i className="fa-solid fa-xmark text-xl"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
            <input
              type="text"
              required
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              placeholder="Ex: Supermercado, Salário..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Valor (R$)</label>
            <input
              type="number"
              step="0.01"
              required
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              placeholder="0,00"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Tipo</label>
              <select
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={type}
                onChange={(e) => setType(e.target.value as TransactionType)}
              >
                <option value="INCOME">Receita</option>
                <option value="EXPENSE">Gasto</option>
                <option value="PROSPECT_INCOME">Receita Futura</option>
                <option value="PROSPECT_EXPENSE">Gasto Futuro</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Data</label>
              <input
                type="date"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={date}
                onChange={(e) => setDate(e.target.value)}
              />
            </div>
          </div>

          {(type === 'EXPENSE' || type === 'PROSPECT_EXPENSE') && (
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Categoria</label>
              <select
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={category}
                onChange={(e) => setCategory(e.target.value as ExpenseCategory)}
              >
                <option value="Urgente">🚨 Urgente</option>
                <option value="Importante">✅ Importante</option>
                <option value="Lazer">🎡 Lazer</option>
                <option value="Desnecessário">💸 Desnecessário</option>
                <option value="Fixo">🏠 Fixo</option>
              </select>
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-indigo-600 text-white py-3 rounded-xl font-semibold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-colors mt-6"
          >
            Adicionar Registro
          </button>
        </form>
      </div>
    </div>
  );
};

import React from 'react';
import { Transaction } from '../types';
import { getDaysInMonth, getFirstDayOfMonth, formatCurrency } from '../utils';

interface FinancialCalendarProps {
  transactions: Transaction[];
  onDateClick: (date: string) => void;
}

export const FinancialCalendar: React.FC<FinancialCalendarProps> = ({ transactions, onDateClick }) => {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);
  const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(now);

  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const blanks = Array.from({ length: firstDay }, (_, i) => i);

  const getTransactionsForDay = (day: number) => {
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    return transactions.filter(t => t.date === dateStr);
  };

  return (
    <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-slate-800 capitalize">{monthName} {year}</h2>
        <div className="flex gap-2">
           <span className="flex items-center gap-1 text-[10px] text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full font-medium">Recebido</span>
           <span className="flex items-center gap-1 text-[10px] text-rose-600 bg-rose-50 px-2 py-0.5 rounded-full font-medium">Gasto</span>
           <span className="flex items-center gap-1 text-[10px] text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full font-medium">Projeção</span>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-2">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sab'].map(d => (
          <div key={d} className="text-center text-xs font-semibold text-slate-400 py-2 uppercase tracking-wider">{d}</div>
        ))}

        {blanks.map(b => (
          <div key={`blank-${b}`} className="aspect-square bg-slate-50/50 rounded-xl"></div>
        ))}

        {days.map(day => {
          const dayTrans = getTransactionsForDay(day);
          const hasIncome = dayTrans.some(t => t.type === 'INCOME');
          const hasExpense = dayTrans.some(t => t.type === 'EXPENSE');
          const hasProspect = dayTrans.some(t => t.type === 'PROSPECT_INCOME' || t.type === 'PROSPECT_EXPENSE');

          return (
            <button
              key={day}
              onClick={() => onDateClick(`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`)}
              className="group relative aspect-square bg-white border border-slate-100 rounded-xl p-1 flex flex-col items-center justify-between hover:bg-indigo-50 transition-colors"
            >
              <span className="text-sm font-medium text-slate-600">{day}</span>
              <div className="flex gap-0.5 mb-1">
                {hasIncome && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>}
                {hasExpense && <div className="w-1.5 h-1.5 rounded-full bg-rose-500"></div>}
                {hasProspect && <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div>}
              </div>

              {/* Tooltip on hover */}
              {dayTrans.length > 0 && (
                 <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover:block z-10 w-32 bg-slate-800 text-white text-[10px] p-2 rounded-lg shadow-xl pointer-events-none">
                   {dayTrans.slice(0, 2).map(t => (
                     <div key={t.id} className="flex justify-between border-b border-slate-700/50 py-0.5">
                       <span className="truncate mr-1">{t.description}</span>
                       <span className={t.type.includes('INCOME') ? 'text-emerald-400' : 'text-rose-400'}>
                        {formatCurrency(t.amount)}
                       </span>
                     </div>
                   ))}
                   {dayTrans.length > 2 && <div className="text-center pt-1 text-slate-400">+{dayTrans.length - 2} mais</div>}
                 </div>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Transaction } from '../types';

interface GeminiAdvisorProps {
  transactions: Transaction[];
  onHand: number;
  projected: number;
}

export const GeminiAdvisor: React.FC<GeminiAdvisorProps> = ({ transactions, onHand, projected }) => {
  const [advice, setAdvice] = useState<string>('');
  const [loading, setLoading] = useState(false);

  const fetchAdvice = async () => {
    if (transactions.length === 0) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const expenseSummary = transactions
        .filter(t => t.type === 'EXPENSE')
        .reduce((acc: any, t) => {
          acc[t.category] = (acc[t.category] || 0) + t.amount;
          return acc;
        }, {});

      const prompt = `Analise meu perfil financeiro e dê 3 dicas curtas e motivadoras em português (máximo 200 caracteres no total).
        Saldo em mãos: R$ ${onHand}
        Saldo projetado: R$ ${projected}
        Categorias de gastos: ${JSON.stringify(expenseSummary)}
        Foque em reduzir gastos desnecessários ou preparar para o futuro.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setAdvice(response.text || 'Continue monitorando seus gastos para manter uma vida financeira saudável!');
    } catch (error) {
      console.error('Error fetching AI advice:', error);
      setAdvice('Dica: Priorize gastos urgentes e tente criar uma reserva de emergência.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
        fetchAdvice();
    }, 1000);
    return () => clearTimeout(timer);
  }, [transactions.length, onHand, projected]);

  return (
    <div className="bg-indigo-900 text-indigo-100 p-6 rounded-3xl shadow-xl relative overflow-hidden">
      <div className="relative z-10">
        <div className="flex items-center gap-2 mb-3">
          <i className="fa-solid fa-wand-sparkles text-indigo-300"></i>
          <h3 className="text-lg font-bold">Finanza Insight (AI)</h3>
        </div>

        {loading ? (
          <div className="animate-pulse space-y-2">
            <div className="h-4 bg-indigo-800 rounded w-3/4"></div>
            <div className="h-4 bg-indigo-800 rounded w-1/2"></div>
          </div>
        ) : (
          <p className="text-sm italic font-light leading-relaxed">
            "{advice || 'Adicione algumas transações para receber dicas personalizadas da nossa IA.'}"
          </p>
        )}
      </div>

      {/* Decorative blobs */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-800 rounded-full blur-3xl -mr-16 -mt-16 opacity-50"></div>
      <div className="absolute bottom-0 left-0 w-24 h-24 bg-indigo-700 rounded-full blur-2xl -ml-12 -mb-12 opacity-30"></div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction } from './types';
import { FinancialCard } from './components/FinancialCard';
import { TransactionForm } from './components/TransactionForm';
import { FinancialCalendar } from './components/FinancialCalendar';
import { GeminiAdvisor } from './components/GeminiAdvisor';
import { calculateFinances, formatCurrency, formatDate } from './utils';

const App: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finanza_transactions');
    return saved ? JSON.parse(saved) : [];
  });
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'calendar'>('overview');
  const [filterDate, setFilterDate] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('finanza_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const stats = useMemo(() => calculateFinances(transactions), [transactions]);

  const addTransaction = (t: Transaction) => {
    setTransactions(prev => [t, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const filteredTransactions = useMemo(() => {
    if (filterDate) {
      return transactions.filter(t => t.date === filterDate);
    }
    return transactions.slice(0, 10); // Last 10
  }, [transactions, filterDate]);

  return (
    <div className="min-h-screen pb-24 md:pb-8 flex flex-col items-center">
      {/* Header */}
      <header className="w-full max-w-5xl px-6 py-8 flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">Finanza</h1>
          <p className="text-slate-500 text-sm">Simplifique sua gestão financeira</p>
        </div>
        <button
          onClick={() => setIsFormOpen(true)}
          className="bg-indigo-600 text-white p-4 rounded-2xl shadow-lg shadow-indigo-200 hover:bg-indigo-700 hover:scale-105 active:scale-95 transition-all"
        >
          <i className="fa-solid fa-plus mr-2"></i>
          <span className="hidden sm:inline">Novo Registro</span>
        </button>
      </header>

      <main className="w-full max-w-5xl px-6 grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column - Stats & Cards */}
        <div className="lg:col-span-2 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FinancialCard
              title="Em Mãos Hoje"
              value={stats.onHand}
              icon="fa-wallet"
              colorClass="bg-emerald-500"
              description="Saldo real disponível agora"
            />
            <FinancialCard
              title="Projeção Final"
              value={stats.projectedTotal}
              icon="fa-chart-line"
              colorClass="bg-indigo-500"
              description="Saldo considerando futuros ganhos/gastos"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="bg-white p-4 rounded-2xl border border-slate-100 flex flex-col">
                <span className="text-xs text-slate-400 font-medium uppercase">Entradas (Mês)</span>
                <span className="text-lg font-bold text-emerald-600">{formatCurrency(stats.monthlyIncome)}</span>
             </div>
             <div className="bg-white p-4 rounded-2xl border border-slate-100 flex flex-col">
                <span className="text-xs text-slate-400 font-medium uppercase">Saídas (Mês)</span>
                <span className="text-lg font-bold text-rose-500">{formatCurrency(stats.monthlyExpenses)}</span>
             </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 w-fit">
            <button
              onClick={() => {setActiveTab('overview'); setFilterDate(null);}}
              className={`px-6 py-2 rounded-xl text-sm font-semibold transition-all ${activeTab === 'overview' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Visão Geral
            </button>
            <button
              onClick={() => setActiveTab('calendar')}
              className={`px-6 py-2 rounded-xl text-sm font-semibold transition-all ${activeTab === 'calendar' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Calendário
            </button>
          </div>

          {activeTab === 'overview' ? (
             <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-bold text-slate-800">
                    {filterDate ? `Registros em ${formatDate(filterDate)}` : 'Últimas Atividades'}
                  </h3>
                  {filterDate && (
                    <button onClick={() => setFilterDate(null)} className="text-xs text-indigo-600 font-medium hover:underline">
                      Limpar filtro
                    </button>
                  )}
                </div>

                <div className="space-y-3">
                  {filteredTransactions.length > 0 ? (
                    filteredTransactions.map(t => (
                      <div key={t.id} className="group bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between transition-all hover:border-indigo-100 hover:shadow-sm">
                        <div className="flex items-center gap-4">
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold ${
                            t.type.includes('INCOME') ? 'bg-emerald-50 text-emerald-600' : 
                            (t.category === 'Urgente' ? 'bg-rose-50 text-rose-600' : 'bg-slate-50 text-slate-600')
                          }`}>
                            {t.category === 'Urgente' ? '!' : (t.type.includes('INCOME') ? 'R' : 'G')}
                          </div>
                          <div>
                            <h4 className="font-semibold text-slate-800">{t.description}</h4>
                            <div className="flex gap-2 items-center">
                              <span className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{t.category}</span>
                              <span className="text-[10px] text-slate-300">•</span>
                              <span className="text-[10px] text-slate-400">{formatDate(t.date)}</span>
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-4">
                          <span className={`font-bold ${t.type.includes('INCOME') ? 'text-emerald-600' : 'text-slate-700'}`}>
                            {t.type.includes('INCOME') ? '+' : '-'} {formatCurrency(t.amount)}
                          </span>
                          <button 
                            onClick={() => deleteTransaction(t.id)}
                            className="text-slate-300 hover:text-rose-400 transition-colors opacity-0 group-hover:opacity-100"
                          >
                            <i className="fa-solid fa-trash-can"></i>
                          </button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-12 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                      <p className="text-slate-400 text-sm">Nenhuma transação encontrada.</p>
                    </div>
                  )}
                </div>
             </div>
          ) : (
            <FinancialCalendar 
              transactions={transactions} 
              onDateClick={(date) => {
                setFilterDate(date);
                setActiveTab('overview');
              }} 
            />
          )}
        </div>

        {/* Right Column - Sidebars */}
        <div className="space-y-6">
          <GeminiAdvisor 
            transactions={transactions} 
            onHand={stats.onHand} 
            projected={stats.projectedTotal} 
          />

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold text-slate-800 mb-4">Metas de Gastos</h3>
            <div className="space-y-4">
              {[
                { label: 'Urgente', value: stats.monthlyExpenses > 0 ? Math.min(100, (transactions.filter(t => t.category === 'Urgente').reduce((a,b) => a+b.amount,0) / stats.monthlyExpenses) * 100) : 0, color: 'bg-rose-500' },
                { label: 'Lazer', value: stats.monthlyExpenses > 0 ? Math.min(100, (transactions.filter(t => t.category === 'Lazer').reduce((a,b) => a+b.amount,0) / stats.monthlyExpenses) * 100) : 0, color: 'bg-amber-500' },
                { label: 'Fixo', value: stats.monthlyExpenses > 0 ? Math.min(100, (transactions.filter(t => t.category === 'Fixo').reduce((a,b) => a+b.amount,0) / stats.monthlyExpenses) * 100) : 0, color: 'bg-indigo-500' },
              ].map(item => (
                <div key={item.label}>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="font-medium text-slate-600">{item.label}</span>
                    <span className="text-slate-400">{Math.round(item.value)}% do mês</span>
                  </div>
                  <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                    <div className={`h-full ${item.color} transition-all duration-1000`} style={{ width: `${item.value}%` }}></div>
                  </div>
                </div>
              ))}
