      if (t.type === 'INCOME') balance += t.amount;
      if (t.type === 'EXPENSE') balance -= t.amount;
    });

    return {
      transactions: dayTrans,
      balance,
      hasIncome: dayTrans.some(t => t.type === 'INCOME'),
