import React, { useMemo } from 'react';
import { Transaction } from '../types';
import { getDaysInMonth, getFirstDayOfMonth, formatCurrency, getMonthLimits } from '../utils';

interface FinancialCalendarProps {
  transactions: Transaction[];
  onDateClick: (date: string) => void;
}

export const FinancialCalendar: React.FC<FinancialCalendarProps> = ({ transactions, onDateClick }) => {
  const { year, month } = getMonthLimits();
  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);
  const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date(year, month));

  // Pre-calculate running balances for the month
  const dailyMetrics = useMemo(() => {
    const metrics: Record<number, { balance: number, onHandAtDay: number, trans: Transaction[] }> = {};
    let runningTotal = 0;

    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const dayTrans = transactions.filter(t => t.date === dateStr);

      let dayBalance = 0;
      dayTrans.forEach(t => {
        const isInc = t.type === 'INCOME' || t.type === 'PROSPECT_INCOME';
        const isExp = t.type === 'EXPENSE' || t.type === 'PROSPECT_EXPENSE';
        if (isInc) dayBalance += t.amount;
        if (isExp) dayBalance -= t.amount;
      });

      runningTotal += dayBalance;
      metrics[day] = { balance: dayBalance, onHandAtDay: runningTotal, trans: dayTrans };
    }
    return metrics;
  }, [transactions, year, month]);

  return (
    <div className="bg-white rounded-[40px] p-8 shadow-sm border border-slate-100">
      <div className="flex justify-between items-center mb-10">
        <h2 className="text-3xl font-black text-slate-800 capitalize">{monthName}</h2>
        <div className="flex gap-2">
           <div className="w-3 h-3 rounded-full bg-emerald-400"></div>
           <div className="w-3 h-3 rounded-full bg-rose-400"></div>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-3">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map(d => (
          <div key={d} className="text-center text-[10px] font-black text-slate-300 py-2 uppercase tracking-widest">{d}</div>
        ))}

        {Array.from({ length: firstDay }).map((_, i) => (
          <div key={`b-${i}`} className="aspect-square bg-slate-50/50 rounded-3xl border border-dashed border-slate-100"></div>
        ))}

        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1;
          const { balance, onHandAtDay, trans } = dailyMetrics[day];
          const hasMovement = trans.length > 0;

          return (
            <button
              key={day}
              onClick={() => onDateClick(`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`)}
              className={`group relative aspect-square rounded-3xl flex flex-col items-center justify-center gap-1 border transition-all hover:scale-105 active:scale-95 ${
                hasMovement ? (balance >= 0 ? 'bg-emerald-50/50 border-emerald-100' : 'bg-rose-50/50 border-rose-100') : 'bg-white border-slate-50'
              }`}
            >
              <span className="text-xs font-black text-slate-600">{day}</span>
              {hasMovement && <div className={`w-1.5 h-1.5 rounded-full ${balance >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>}

              {/* Popover overlay on click/hover simulated by relative tooltip */}
              <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity z-10 pointer-events-none">
                 <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-4 w-40 bg-slate-900 text-white p-3 rounded-2xl shadow-2xl text-[10px]">
                    <div className="flex justify-between mb-1 border-b border-white/10 pb-1">
                       <span className="font-bold opacity-60">Fluxo Dia:</span>
                       <span className={balance >= 0 ? 'text-emerald-400' : 'text-rose-400'}>{formatCurrency(balance)}</span>
                    </div>
                    <div className="flex justify-between font-black text-indigo-300">
                       <span>Saldo Total:</span>
                       <span>{formatCurrency(onHandAtDay)}</span>
                    </div>
                 </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

