        )}

        {activeTab === 'fixed' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <h2 className="text-2xl font-black px-2">Custos Fixos e Assinaturas</h2>
            <div className="grid grid-cols-1 gap-4">
              {transactions.filter(t => t.isFixed).map(t => (
                <div key={t.id} className="bg-white p-6 rounded-[32px] border border-slate-100 flex items-center justify-between">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl shadow-inner">
                      <i className="fa-solid fa-repeat"></i>
                    </div>
                    <div>
                      <p className="font-black text-lg text-slate-800">{t.description}</p>
                      <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Referência: Todo dia {t.fixedDay}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xl font-black text-rose-500">{formatCurrency(t.amount)}</p>
                    <button onClick={() => handleDelete(t.id)} className="text-[10px] font-bold text-slate-300 hover:text-rose-400 uppercase">Remover fixo</button>
                  </div>
                </div>
              ))}
              {transactions.filter(t => t.isFixed).length === 0 && <p className="text-center py-20 text-slate-400 font-bold italic">Nenhum custo fixo cadastrado.</p>}
            </div>
            <div className="bg-indigo-50 p-6 rounded-[32px] border border-indigo-100">
               <p className="text-sm font-bold text-indigo-900">Total em Custos Fixos: <span className="text-lg font-black">{formatCurrency(transactions.filter(t => t.isFixed).reduce((acc, c) => acc + c.amount, 0))}</span></p>
            </div>
          </div>
        )}
      </main>

      {/* BOTTOM TAB NAVIGATION */}
      <nav className="fixed bottom-6 left-6 right-6 h-20 bg-slate-900 text-white rounded-[32px] shadow-2xl z-40 flex items-center justify-around px-4 border border-white/5">
        {[
          { id: 'home', icon: 'fa-house-chimney', label: 'Início' },
          { id: 'extract', icon: 'fa-list-check', label: 'Extrato' },
          { id: 'calendar', icon: 'fa-calendar-days', label: 'Flow' },
          { id: 'analytics', icon: 'fa-chart-pie', label: 'Metas' },
          { id: 'fixed', icon: 'fa-clock-rotate-left', label: 'Fixos' }
        ].map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id as Tab)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 ${activeTab === item.id ? 'scale-110' : 'opacity-40 hover:opacity-100'}`}
          >
            <div className={`w-10 h-10 flex items-center justify-center rounded-2xl transition-colors ${activeTab === item.id ? 'bg-white text-slate-900' : ''}`}>
              <i className={`fa-solid ${item.icon}`}></i>
            </div>
            <span className={`text-[8px] font-black uppercase tracking-widest ${activeTab === item.id ? 'opacity-100' : 'opacity-0'}`}>{item.label}</span>
          </button>
        ))}
      </nav>

      {/* FLOATING QUICK ADD (on Home Tab only or everywhere?) */}
      {activeTab !== 'home' && (
        <button 
          onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }}
          className="fixed bottom-28 right-8 w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center z-40 hover:scale-110 active:scale-95 transition-all animate-in zoom-in"
        >
          <i className="fa-solid fa-plus text-2xl"></i>
        </button>
      )}

      {/* FORM MODAL */}
      {isFormOpen && (
        <TransactionForm 
          onAdd={handleAdd} 
          onClose={() => setIsFormOpen(false)} 
          initialData={editingTransaction}
          customCategories={customCategories}
          onAddCategory={(c) => setCustomCategories(prev => [...prev, c])}
        />
      )}
    </div>
  );
};

export default App;

