import React, { useState } from 'react';
import { TransactionType, Transaction } from '../types';

interface TransactionFormProps {
  onAdd: (transaction: Transaction) => void;
  onClose: () => void;
  initialData?: Transaction | null;
  customCategories: string[];
  onAddCategory: (cat: string) => void;
}

export const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, onClose, initialData, customCategories, onAddCategory }) => {
  const [description, setDescription] = useState(initialData?.description || '');
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [type, setType] = useState<TransactionType>(initialData?.type || 'EXPENSE');
  const [category, setCategory] = useState(initialData?.category || 'Importante');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [isFixed, setIsFixed] = useState(initialData?.isFixed || false);
  const [recurrenceMonths, setRecurrenceMonths] = useState(initialData?.recurrenceMonths?.toString() || '0');
  const [newCat, setNewCat] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const transactionData: Transaction = {
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      description,
      amount: parseFloat(amount),
      type,
      category: isFixed ? 'Custo Fixo' : (type.includes('INCOME') ? 'Receita' : category),
      date,
      isFixed,
      fixedDay: isFixed ? new Date(date + 'T12:00:00').getDate() : undefined,
      recurrenceMonths: isFixed ? parseInt(recurrenceMonths) : undefined
    };

    onAdd(transactionData);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-lg rounded-[48px] p-8 shadow-2xl animate-in fade-in zoom-in duration-300 overflow-y-auto max-h-[90vh] border border-white/20">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">{initialData ? 'Editar Registro' : 'Novo Lançamento'}</h2>
          <button onClick={onClose} className="w-12 h-12 flex items-center justify-center bg-slate-100 text-slate-500 rounded-[20px] hover:bg-rose-50 hover:text-rose-500 transition-all">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="flex gap-2 p-1.5 bg-slate-100 rounded-[24px]">
            {['INCOME', 'EXPENSE'].map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setType(t as TransactionType)}
                className={`flex-1 py-3.5 rounded-[18px] text-xs font-black transition-all uppercase tracking-widest ${type.includes(t) ? 'bg-white text-indigo-600 shadow-lg shadow-indigo-100/50' : 'text-slate-400'}`}
              >
                {t === 'INCOME' ? 'Ganhos' : 'Gastos'}
              </button>
            ))}
          </div>

          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase ml-4 mb-2 block tracking-widest">Descrição</label>
              <input
                type="text" required value={description} onChange={(e) => setDescription(e.target.value)}
                className="w-full px-6 py-4 rounded-[24px] bg-slate-50 border-2 border-transparent focus:border-indigo-500/20 focus:bg-white focus:outline-none transition-all font-bold text-slate-700"
                placeholder="Ex: Aluguel, Supermercado..."
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-4 mb-2 block tracking-widest">Valor R$</label>
                <input
                  type="number" step="0.01" required value={amount} onChange={(e) => setAmount(e.target.value)}
                  className="w-full px-6 py-4 rounded-[24px] bg-slate-50 border-2 border-transparent focus:border-indigo-500/20 focus:bg-white focus:outline-none transition-all font-black text-lg text-slate-800"
                  placeholder="0,00"
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-4 mb-2 block tracking-widest">Data</label>
                <input
                  type="date" required value={date} onChange={(e) => setDate(e.target.value)}
                  className="w-full px-6 py-4 rounded-[24px] bg-slate-50 border-2 border-transparent focus:border-indigo-500/20 focus:bg-white focus:outline-none transition-all font-bold text-slate-700"
                />
              </div>
            </div>
          </div>

          <div className="p-6 bg-indigo-50 rounded-[32px] border border-indigo-100/50 space-y-4">
             <div className="flex items-center gap-3">
               <input 
                 type="checkbox" id="fixed" checked={isFixed} onChange={(e) => setIsFixed(e.target.checked)}
                 className="w-6 h-6 rounded-lg text-indigo-600 border-indigo-200 focus:ring-indigo-500" 
               />
               <label htmlFor="fixed" className="text-sm font-black text-indigo-900 cursor-pointer">Custo Fixo Mensal</label>
             </div>

             {isFixed && (
               <div className="animate-in slide-in-from-top-2 duration-300">
                 <label className="text-[10px] font-black text-indigo-400 uppercase mb-2 block tracking-widest">Período de Repetição (Meses)</label>
                 <input 
                   type="number" value={recurrenceMonths} onChange={(e) => setRecurrenceMonths(e.target.value)}
                   className="w-full px-4 py-3 rounded-xl bg-white border-none focus:ring-2 focus:ring-indigo-500 font-bold text-indigo-600"
                   placeholder="0 = Indeterminado"
                 />
                 <p className="text-[10px] text-indigo-400 mt-2 italic font-medium">Use '0' para gastos que se repetem todos os meses.</p>
               </div>
             )}
          </div>

          {!isFixed && type === 'EXPENSE' && (
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-4 block tracking-widest">Categoria</label>
              <div className="flex flex-wrap gap-2">
                {[...customCategories, 'Urgente', 'Importante', 'Lazer', 'Desnecessário'].map(cat => (
                  <button
                    key={cat} type="button" onClick={() => setCategory(cat)}
                    className={`px-5 py-2.5 rounded-full text-xs font-black transition-all border-2 ${category === cat ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-100'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
              <div className="flex gap-2">
                <input 
                  type="text" placeholder="Criar categoria..." value={newCat} onChange={(e) => setNewCat(e.target.value)}
                  className="flex-1 px-5 py-3 rounded-2xl bg-slate-50 border-none text-xs font-bold focus:ring-2 focus:ring-indigo-200" 
                />
                <button 
                  type="button" onClick={() => { if(newCat) { onAddCategory(newCat); setCategory(newCat); setNewCat(''); } }}
                  className="bg-indigo-100 text-indigo-600 px-6 py-3 rounded-2xl text-xs font-black hover:bg-indigo-200 transition-colors"
                >+ Criar</button>
              </div>
            </div>
          )}

          <button type="submit" className="w-full bg-slate-900 text-white py-6 rounded-[32px] font-black shadow-2xl shadow-slate-200 hover:bg-indigo-700 transition-all uppercase tracking-[0.2em] text-sm mt-4">
            {initialData ? 'Salvar Alterações' : 'Confirmar Registro'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, FinancialStats } from './types';
import { TransactionForm } from './components/TransactionForm';
import { FinancialCalendar } from './components/FinancialCalendar';
import { SummaryHeader } from './components/SummaryHeader';
import { GeminiAdvisor } from './components/GeminiAdvisor';
import { calculateFinances, formatCurrency, formatDate, getCategoryTotals } from './utils';

type Tab = 'home' | 'extract' | 'calendar' | 'analytics' | 'fixed';

const App: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finanza_v3_data');
    return saved ? JSON.parse(saved) : [];
  });
  const [customCategories, setCustomCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('finanza_v3_cats');
    return saved ? JSON.parse(saved) : ['Comida', 'Assinaturas', 'Educação'];
  });
  const [activeTab, setActiveTab] = useState<Tab>('home');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [filterDate, setFilterDate] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('finanza_v3_data', JSON.stringify(transactions));
    localStorage.setItem('finanza_v3_cats', JSON.stringify(customCategories));
  }, [transactions, customCategories]);

  const stats = useMemo(() => calculateFinances(transactions), [transactions]);
  const categoryTotals = useMemo(() => getCategoryTotals(transactions), [transactions]);

  const handleAdd = (t: Transaction) => {
    if (editingTransaction) {
      setTransactions(prev => prev.map(item => item.id === t.id ? t : item));
      setEditingTransaction(null);
    } else {
      setTransactions(prev => [t, ...prev]);
    }
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Deseja realmente excluir este lançamento?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const filteredExtract = useMemo(() => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    return transactions.filter(t => {
      const d = new Date(t.date + 'T12:00:00');
      const isThisMonth = d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      return filterDate ? t.date === filterDate : isThisMonth;
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [transactions, filterDate]);

  const HealthCard = () => (
    <div className="bg-white p-8 rounded-[40px] border border-slate-100 flex items-center justify-between shadow-sm relative overflow-hidden group">
      <div className="relative z-10">
        <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-1">Status de Saúde</h4>
        <p className={`text-xs font-bold ${stats.healthScore > 70 ? 'text-emerald-500' : stats.healthScore > 40 ? 'text-amber-500' : 'text-rose-500'}`}>
          {stats.healthScore > 70 ? 'Tudo sob controle!' : stats.healthScore > 40 ? 'Requer atenção.' : 'Ajuste necessário!'}
        </p>
      </div>
      <div className="flex items-center gap-6 relative z-10">
        <div className="relative">
            <svg className="w-16 h-16 transform -rotate-90">
                <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-100" />
                <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" 
                    strokeDasharray={175.9} strokeDashoffset={175.9 - (175.9 * stats.healthScore) / 100}
                    className={`${stats.healthScore > 70 ? 'text-emerald-500' : stats.healthScore > 40 ? 'text-amber-500' : 'text-rose-500'} transition-all duration-1000 ease-out`} />
            </svg>
            <span className="absolute inset-0 flex items-center justify-center text-xs font-black text-slate-800">{stats.healthScore.toFixed(0)}%</span>
        </div>
      </div>
      <div className="absolute top-0 right-0 w-32 h-32 bg-slate-50 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform"></div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#FDFDFD] flex flex-col font-sans text-slate-900 pb-32">

      {/* PERSISTENT SUMMARY NO TOPO */}
      {activeTab !== 'home' && (
        <SummaryHeader onHand={stats.onHand} projected={stats.projectedTotal} futureExpenses={stats.futureExpenses} />
      )}

      <main className="flex-1 w-full max-w-4xl mx-auto px-6 py-10">
        {activeTab === 'home' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-700">
            <header className="flex justify-between items-end">
               <div>
                 <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-2 ml-1">My Dashboard</p>
                 <h1 className="text-5xl font-black tracking-tighter text-slate-900 leading-none">Finanza.</h1>
               </div>
               <div className="bg-indigo-600 text-white w-16 h-16 rounded-[28px] flex items-center justify-center shadow-2xl shadow-indigo-200">
                 <i className="fa-solid fa-gem text-2xl"></i>
               </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="bg-white p-10 rounded-[56px] shadow-sm border border-slate-100 relative overflow-hidden group">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Saldo em Mãos</p>
                  <h2 className={`text-4xl font-black tracking-tighter ${stats.onHand >= 0 ? 'text-slate-900' : 'text-rose-600'}`}>
                    {formatCurrency(stats.onHand)}
                  </h2>
                  <div className="absolute top-0 right-0 p-10 opacity-[0.03] text-8xl group-hover:scale-110 transition-transform">
                    <i className="fa-solid fa-wallet"></i>
                  </div>
               </div>
               <div className="bg-slate-900 p-10 rounded-[56px] shadow-2xl shadow-slate-200 text-white relative overflow-hidden group">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Projeção do Mês</p>
                  <h2 className="text-4xl font-black tracking-tighter text-white">{formatCurrency(stats.projectedTotal)}</h2>
                  <div className="absolute top-0 right-0 p-10 opacity-10 text-8xl group-hover:rotate-12 transition-transform">
                    <i className="fa-solid fa-chart-line"></i>
                  </div>
               </div>
            </div>

            <div className="bg-rose-50 p-8 rounded-[48px] border border-rose-100/50 flex items-center justify-between">
              <div className="flex items-center gap-5">
                <div className="bg-rose-500 text-white w-12 h-12 rounded-[20px] flex items-center justify-center shadow-xl shadow-rose-200/50">
                  <i className="fa-solid fa-calendar-check"></i>
                </div>
                <div>
                  <h4 className="text-[10px] font-black text-rose-900 uppercase tracking-widest">Gastos Futuros</h4>
                  <p className="text-xl font-black text-rose-600 tracking-tighter">{formatCurrency(stats.futureExpenses)}</p>
                </div>
              </div>
              <button onClick={() => setActiveTab('fixed')} className="w-10 h-10 rounded-full bg-white text-rose-300 hover:text-rose-500 flex items-center justify-center transition-colors">
                <i className="fa-solid fa-chevron-right"></i>
              </button>
            </div>

            <HealthCard />

            <GeminiAdvisor transactions={transactions} onHand={stats.onHand} projected={stats.projectedTotal} />

            <button 
              onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }}
              className="w-full bg-indigo-600 text-white py-8 rounded-[40px] font-black text-xl shadow-2xl shadow-indigo-100 hover:bg-indigo-700 hover:-translate-y-1 transition-all active:translate-y-0 tracking-widest uppercase"
            >
              <i className="fa-solid fa-plus-circle mr-3"></i> Adicionar
            </button>
          </div>
        )}

        {activeTab === 'extract' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center px-4">
              <h2 className="text-3xl font-black tracking-tighter">Extrato Detalhado</h2>
              {filterDate && (
                 <button onClick={() => setFilterDate(null)} className="text-[10px] font-black text-indigo-600 uppercase bg-indigo-50 px-4 py-2 rounded-full">Limpar Filtro</button>
              )}
            </div>
            <div className="space-y-4">
              {filteredExtract.map(t => (
                <div key={t.id} className="bg-white p-6 rounded-[36px] border border-slate-100 flex justify-between items-center group hover:border-indigo-100 hover:shadow-xl transition-all duration-300">
                  <div className="flex items-center gap-5">
                    <div className={`w-14 h-14 rounded-[22px] flex items-center justify-center text-xl shadow-inner ${t.type.includes('INCOME') ? 'bg-emerald-50 text-emerald-500' : 'bg-slate-50 text-slate-400'}`}>
                      <i className={`fa-solid ${t.type.includes('INCOME') ? 'fa-arrow-up-long' : 'fa-arrow-down-long'}`}></i>
                    </div>
                    <div>
                      <p className="font-black text-lg text-slate-800 tracking-tight leading-none mb-1">{t.description}</p>
                      <div className="flex gap-2 items-center">
                        <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{t.category}</span>
                        <span className="text-slate-200">•</span>
                        <span className="text-[10px] text-slate-400 font-bold">{formatDate(t.date)}</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-6">
                    <div className="text-right">
                      <p className={`font-black text-xl tracking-tighter ${t.type.includes('INCOME') ? 'text-emerald-500' : 'text-slate-900'}`}>
                        {t.type.includes('INCOME') ? '+' : '-'}{formatCurrency(t.amount)}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => handleEdit(t)} className="w-10 h-10 rounded-[16px] bg-slate-50 text-slate-300 hover:text-indigo-600 transition-colors"><i className="fa-solid fa-pen text-sm"></i></button>
                      <button onClick={() => handleDelete(t.id)} className="w-10 h-10 rounded-[16px] bg-rose-50/50 text-rose-200 hover:text-rose-500 transition-colors"><i className="fa-solid fa-trash text-sm"></i></button>
                    </div>
                  </div>
                </div>
              ))}
