import React, { useState } from 'react';
import { TransactionType, Transaction } from '../types';

interface TransactionFormProps {
  onAdd: (transaction: Transaction) => void;
  onClose: () => void;
  initialData?: Transaction | null;
  customCategories: string[];
  onAddCategory: (cat: string) => void;
}

export const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, onClose, initialData, customCategories, onAddCategory }) => {
  const [description, setDescription] = useState(initialData?.description || '');
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [type, setType] = useState<TransactionType>(initialData?.type || 'EXPENSE');
  const [category, setCategory] = useState(initialData?.category || 'Importante');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [isFixed, setIsFixed] = useState(initialData?.isFixed || false);
  const [recurrenceMonths, setRecurrenceMonths] = useState(initialData?.recurrenceMonths?.toString() || '0');
  const [newCat, setNewCat] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const transactionData: Transaction = {
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      description,
      amount: parseFloat(amount),
      type,
      category: isFixed ? 'Custo Fixo' : (type.includes('INCOME') ? 'Receita' : category),
      date,
      isFixed,
      fixedDay: isFixed ? new Date(date + 'T12:00:00').getDate() : undefined,
      recurrenceMonths: isFixed ? parseInt(recurrenceMonths) : undefined
    };

    onAdd(transactionData);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-800/20 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-xl p-6 shadow-xl border border-slate-100 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-6 border-b border-slate-50 pb-4">
          <h2 className="text-xl font-bold text-slate-700 tracking-tight">{initialData ? 'Editar' : 'Novo Registro'}</h2>
          <button onClick={onClose} className="text-slate-300 hover:text-slate-500 transition-colors">
            <i className="fa-solid fa-xmark text-lg"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex bg-slate-50 p-1 rounded-lg border border-slate-100">
            {['INCOME', 'EXPENSE'].map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setType(t as TransactionType)}
                className={`flex-1 py-2 rounded-md text-[10px] font-bold transition-all uppercase tracking-widest ${type.includes(t) ? 'bg-white text-indigo-500 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'INCOME' ? 'Entrada' : 'Saída'}
              </button>
            ))}
          </div>

          <div className="space-y-3">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">O que é?</label>
              <input
                type="text" required value={description} onChange={(e) => setDescription(e.target.value)}
                className="w-full px-4 py-3 rounded-lg bg-white border border-slate-200 focus:border-indigo-300 focus:outline-none transition-all text-sm"
                placeholder="Ex: Aluguel, Supermercado..."
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">Valor</label>
                <input
                  type="number" step="0.01" required value={amount} onChange={(e) => setAmount(e.target.value)}
                  className="w-full px-4 py-3 rounded-lg bg-white border border-slate-200 focus:border-indigo-300 focus:outline-none transition-all text-sm font-bold"
                  placeholder="0,00"
                />
              </div>
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">Data</label>
                <input
                  type="date" required value={date} onChange={(e) => setDate(e.target.value)}
                  className="w-full px-4 py-3 rounded-lg bg-white border border-slate-200 focus:border-indigo-300 focus:outline-none transition-all text-sm"
                />
              </div>
            </div>
          </div>

          <div className="p-4 bg-slate-50 rounded-lg border border-slate-100 space-y-3">
             <div className="flex items-center gap-2">
               <input 
                 type="checkbox" id="fixed" checked={isFixed} onChange={(e) => setIsFixed(e.target.checked)}
                 className="w-4 h-4 rounded text-indigo-600 border-slate-300" 
               />
               <label htmlFor="fixed" className="text-xs font-bold text-slate-600 cursor-pointer">Custo Fixo Mensal</label>
             </div>

             {isFixed && (
               <div className="space-y-2">
                 <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block">Duração (Meses)</label>
                 <input 
                   type="number" value={recurrenceMonths} onChange={(e) => setRecurrenceMonths(e.target.value)}
                   className="w-full px-3 py-2 rounded border border-slate-200 text-xs focus:ring-1 focus:ring-indigo-300 outline-none"
                   placeholder="0 = Vitalício"
                 />
               </div>
             )}
          </div>

          {!isFixed && type === 'EXPENSE' && (
            <div className="space-y-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block">Categoria</label>
              <div className="flex flex-wrap gap-1.5">
                {[...customCategories, 'Urgente', 'Importante', 'Lazer', 'Desnecessário'].map(cat => (
                  <button
                    key={cat} type="button" onClick={() => setCategory(cat)}
                    className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-all border ${category === cat ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-slate-400'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
              <div className="flex gap-2">
                <input 
                  type="text" placeholder="Outra..." value={newCat} onChange={(e) => setNewCat(e.target.value)}
                  className="flex-1 px-3 py-2 rounded border border-slate-100 text-[10px] outline-none" 
                />
                <button 
                  type="button" onClick={() => { if(newCat) { onAddCategory(newCat); setCategory(newCat); setNewCat(''); } }}
                  className="text-indigo-400 text-[10px] font-bold px-2"
                >+ Add</button>
              </div>
            </div>
          )}

          <button type="submit" className="w-full bg-slate-700 text-white py-4 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-slate-800 transition-all mt-2 shadow-sm">
            {initialData ? 'Atualizar' : 'Salvar Registro'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Transaction } from '../types';
import { getDaysInMonth, getFirstDayOfMonth, formatCurrency, getMonthLimits } from '../utils';

interface FinancialCalendarProps {
  transactions: Transaction[];
  onDateClick: (date: string) => void;
}

export const FinancialCalendar: React.FC<FinancialCalendarProps> = ({ transactions, onDateClick }) => {
  const { year, month } = getMonthLimits();
  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);
  const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date(year, month));

  const dailyMetrics = useMemo(() => {
    const metrics: Record<number, { balance: number, onHandAtDay: number, trans: Transaction[] }> = {};
    let runningTotal = 0;

    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const dayTrans = transactions.filter(t => t.date === dateStr);

      let dayBalance = 0;
      dayTrans.forEach(t => {
        const isInc = t.type === 'INCOME' || t.type === 'PROSPECT_INCOME';
        const isExp = t.type === 'EXPENSE' || t.type === 'PROSPECT_EXPENSE';
        if (isInc) dayBalance += t.amount;
        if (isExp) dayBalance -= t.amount;
      });

      runningTotal += dayBalance;
      metrics[day] = { balance: dayBalance, onHandAtDay: runningTotal, trans: dayTrans };
    }
    return metrics;
  }, [transactions, year, month]);

  return (
    <div className="bg-white rounded-xl p-5 border border-slate-100 shadow-sm">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-bold text-slate-700 capitalize tracking-tight">{monthName} {year}</h2>
        <div className="flex gap-3">
           <div className="flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-emerald-300"></div><span className="text-[8px] font-bold text-slate-300 uppercase">Ganhos</span></div>
           <div className="flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-rose-300"></div><span className="text-[8px] font-bold text-slate-300 uppercase">Gastos</span></div>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1">
        {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map(d => (
          <div key={d} className="text-center text-[9px] font-bold text-slate-300 py-1 uppercase">{d}</div>
        ))}

        {Array.from({ length: firstDay }).map((_, i) => (
          <div key={`b-${i}`} className="aspect-square bg-slate-50/30 rounded-md"></div>
        ))}

        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1;
          const { balance, trans } = dailyMetrics[day];
          const hasMovement = trans.length > 0;

          return (
            <button
              key={day}
              onClick={() => onDateClick(`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`)}
              className={`group relative aspect-square rounded-lg flex flex-col items-center justify-center gap-0.5 border transition-all hover:bg-slate-50 active:scale-95 ${
                hasMovement ? 'border-slate-100 bg-white' : 'border-transparent'
              }`}
            >
              <span className="text-[10px] font-bold text-slate-500">{day}</span>
              <div className="flex gap-0.5">
                {trans.some(t => t.type.includes('INCOME')) && <div className="w-1 h-1 rounded-full bg-emerald-400"></div>}
                {trans.some(t => t.type.includes('EXPENSE')) && <div className="w-1 h-1 rounded-full bg-rose-400"></div>}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

