export type TransactionType = 'INCOME' | 'EXPENSE' | 'PROSPECT_INCOME' | 'PROSPECT_EXPENSE';

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: string;
  date: string; // ISO YYYY-MM-DD
  isFixed: boolean;
  fixedDay?: number;
  recurrenceMonths?: number; // 0 para indeterminado, ou número de meses
}

export interface FinancialStats {
  onHand: number;
  projectedTotal: number;
  futureExpenses: number;
  monthlyIncome: number;
  monthlyExpenses: number;
  healthScore: number;
}

export type Tab = 'home' | 'extract' | 'calendar' | 'analytics' | 'fixed' | 'settings';

import React, { useState } from 'react';
import { TransactionType, Transaction } from '../types';

interface TransactionFormProps {
  onAdd: (transaction: Transaction) => void;
  onClose: () => void;
  initialData?: Transaction | null;
  customCategories: string[];
  onAddCategory: (cat: string) => void;
}

export const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, onClose, initialData, customCategories, onAddCategory }) => {
  const [description, setDescription] = useState(initialData?.description || '');
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [type, setType] = useState<TransactionType>(initialData?.type || 'EXPENSE');
  const [category, setCategory] = useState(initialData?.category || 'Importante');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [isFixed, setIsFixed] = useState(initialData?.isFixed || false);
  const [recurrenceMonths, setRecurrenceMonths] = useState(initialData?.recurrenceMonths?.toString() || '0');
  const [newCat, setNewCat] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const transactionData: Transaction = {
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      description,
      amount: parseFloat(amount),
      type,
      category: isFixed ? 'Custo Fixo' : (type.includes('INCOME') ? 'Receita' : category),
      date,
      isFixed,
      fixedDay: isFixed ? new Date(date + 'T12:00:00').getDate() : undefined,
      recurrenceMonths: isFixed ? parseInt(recurrenceMonths) : undefined
    };

    onAdd(transactionData);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-800/20 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-lg p-5 shadow-xl border border-slate-100 overflow-y-auto max-h-[90vh]">
        <div className="flex justify-between items-center mb-5 border-b border-slate-50 pb-3">
          <h2 className="text-lg font-bold text-slate-700 tracking-tight">{initialData ? 'Editar Registro' : 'Novo Lançamento'}</h2>
          <button onClick={onClose} className="text-slate-300 hover:text-slate-500 transition-colors">
            <i className="fa-solid fa-xmark text-lg"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex bg-slate-50 p-1 rounded border border-slate-100">
            {['INCOME', 'EXPENSE'].map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setType(t as TransactionType)}
                className={`flex-1 py-1.5 rounded text-[9px] font-bold transition-all uppercase tracking-widest ${type.includes(t) ? 'bg-white text-blue-500 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'INCOME' ? 'Entrada' : 'Saída'}
              </button>
            ))}
          </div>

          <div className="space-y-3">
            <div>
              <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">Descrição</label>
              <input
                type="text" required value={description} onChange={(e) => setDescription(e.target.value)}
                className="w-full px-3 py-2 rounded border border-slate-200 focus:border-blue-300 focus:outline-none transition-all text-xs"
                placeholder="Ex: Aluguel, Supermercado..."
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">Valor</label>
                <input
                  type="number" step="0.01" required value={amount} onChange={(e) => setAmount(e.target.value)}
                  className="w-full px-3 py-2 rounded border border-slate-200 focus:border-blue-300 focus:outline-none transition-all text-xs font-bold"
                  placeholder="0,00"
                />
              </div>
              <div>
                <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">Data</label>
                <input
                  type="date" required value={date} onChange={(e) => setDate(e.target.value)}
                  className="w-full px-3 py-2 rounded border border-slate-200 focus:border-blue-300 focus:outline-none transition-all text-xs"
                />
              </div>
            </div>
          </div>

          <div className="p-3 bg-slate-50 rounded border border-slate-100 space-y-2">
             <div className="flex items-center gap-2">
               <input 
                 type="checkbox" id="fixed" checked={isFixed} onChange={(e) => setIsFixed(e.target.checked)}
                 className="w-3.5 h-3.5 rounded text-blue-600 border-slate-300" 
               />
               <label htmlFor="fixed" className="text-[10px] font-bold text-slate-600 cursor-pointer">Custo Fixo Mensal</label>
             </div>

             {isFixed && (
               <div className="space-y-1">
                 <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest block">Duração (Meses)</label>
                 <input 
                   type="number" value={recurrenceMonths} onChange={(e) => setRecurrenceMonths(e.target.value)}
                   className="w-full px-2 py-1.5 rounded border border-slate-200 text-[10px] focus:ring-1 focus:ring-blue-300 outline-none"
                   placeholder="0 = Vitalício"
                 />
               </div>
             )}
          </div>

          {!isFixed && type === 'EXPENSE' && (
            <div className="space-y-2">
              <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest block">Categoria</label>
              <div className="flex flex-wrap gap-1">
                {[...customCategories, 'Urgente', 'Importante', 'Lazer', 'Desnecessário'].map(cat => (
                  <button
                    key={cat} type="button" onClick={() => setCategory(cat)}
                    className={`px-2 py-1 rounded text-[9px] font-bold transition-all border ${category === cat ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-100 text-slate-400'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
              <div className="flex gap-2 items-center">
                <input 
                  type="text" placeholder="Outra..." value={newCat} onChange={(e) => setNewCat(e.target.value)}
                  className="flex-1 px-2 py-1.5 rounded border border-slate-100 text-[9px] outline-none" 
                />
                <button 
                  type="button" onClick={() => { if(newCat) { onAddCategory(newCat); setCategory(newCat); setNewCat(''); } }}
                  className="text-blue-400 text-[9px] font-bold"
                >+ Criar</button>
              </div>
            </div>
          )}

          <button type="submit" className="w-full bg-slate-700 text-white py-3 rounded font-bold text-[10px] uppercase tracking-widest hover:bg-slate-800 transition-all mt-2 shadow-sm">
            {initialData ? 'Atualizar Dados' : 'Salvar Registro'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Transaction } from '../types';
import { getDaysInMonth, getFirstDayOfMonth, formatCurrency, getMonthLimits } from '../utils';

interface FinancialCalendarProps {
  transactions: Transaction[];
  onDateClick: (date: string) => void;
}

export const FinancialCalendar: React.FC<FinancialCalendarProps> = ({ transactions, onDateClick }) => {
  const { year, month } = getMonthLimits();
  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);
  const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date(year, month));

  const dailyMetrics = useMemo(() => {
    const metrics: Record<number, { balance: number, onHandAtDay: number, trans: Transaction[] }> = {};
    let runningTotal = 0;

    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const dayTrans = transactions.filter(t => t.date === dateStr);

      let dayBalance = 0;
      dayTrans.forEach(t => {
        const isInc = t.type === 'INCOME' || t.type === 'PROSPECT_INCOME';
        const isExp = t.type === 'EXPENSE' || t.type === 'PROSPECT_EXPENSE';
        if (isInc) dayBalance += t.amount;
        if (isExp) dayBalance -= t.amount;
      });

      runningTotal += dayBalance;
      metrics[day] = { balance: dayBalance, onHandAtDay: runningTotal, trans: dayTrans };
    }
    return metrics;
  }, [transactions, year, month]);

  return (
    <div className="bg-white rounded-lg p-4 border border-slate-100 shadow-sm">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-base font-bold text-slate-700 capitalize tracking-tight">{monthName} {year}</h2>
        <div className="flex gap-2">
           <div className="flex items-center gap-1"><div className="w-1 h-1 rounded-full bg-emerald-400"></div><span className="text-[7px] font-bold text-slate-300 uppercase">Ganhos</span></div>
           <div className="flex items-center gap-1"><div className="w-1 h-1 rounded-full bg-rose-400"></div><span className="text-[7px] font-bold text-slate-300 uppercase">Gastos</span></div>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-0.5">
        {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map(d => (
          <div key={d} className="text-center text-[8px] font-bold text-slate-300 py-1 uppercase">{d}</div>
        ))}

        {Array.from({ length: firstDay }).map((_, i) => (
          <div key={`b-${i}`} className="aspect-square bg-slate-50/20 rounded"></div>
        ))}

        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1;
          const { balance, trans } = dailyMetrics[day];
          const hasMovement = trans.length > 0;

          return (
            <button
              key={day}
              onClick={() => onDateClick(`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`)}
              className={`group relative aspect-square rounded flex flex-col items-center justify-center gap-0.5 border transition-all hover:bg-slate-50 active:scale-95 ${
                hasMovement ? 'border-slate-100 bg-white' : 'border-transparent'
              }`}
            >
              <span className="text-[9px] font-bold text-slate-500">{day}</span>
              <div className="flex gap-0.5">
                {trans.some(t => t.type.includes('INCOME')) && <div className="w-0.5 h-0.5 rounded-full bg-emerald-400"></div>}
                {trans.some(t => t.type.includes('EXPENSE')) && <div className="w-0.5 h-0.5 rounded-full bg-rose-400"></div>}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, FinancialStats, Tab } from './types';
import { TransactionForm } from './components/TransactionForm';
import { FinancialCalendar } from './components/FinancialCalendar';
import { SummaryHeader } from './components/SummaryHeader';
import { GeminiAdvisor } from './components/GeminiAdvisor';
import { calculateFinances, formatCurrency, formatDate, getCategoryTotals } from './utils';

const App: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finanza_v5_data');
    return saved ? JSON.parse(saved) : [];
  });
  const [customCategories, setCustomCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('finanza_v5_cats');
    return saved ? JSON.parse(saved) : ['Alimentação', 'Transporte'];
  });
  const [activeTab, setActiveTab] = useState<Tab>('home');
  const [language, setLanguage] = useState<'pt' | 'en' | 'es' | 'fr'>('pt');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [filterDate, setFilterDate] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('finanza_v5_data', JSON.stringify(transactions));
    localStorage.setItem('finanza_v5_cats', JSON.stringify(customCategories));
  }, [transactions, customCategories]);

  const stats = useMemo(() => calculateFinances(transactions), [transactions]);
  const categoryTotals = useMemo(() => getCategoryTotals(transactions), [transactions]);

  const handleAdd = (t: Transaction) => {
    if (editingTransaction) {
      setTransactions(prev => prev.map(item => item.id === t.id ? t : item));
      setEditingTransaction(null);
    } else {
      setTransactions(prev => [t, ...prev]);
    }
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Excluir este lançamento permanentemente?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const filteredExtract = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    return transactions.filter(t => {
      const d = new Date(t.date + 'T12:00:00');
      const isThisMonth = d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      return filterDate ? t.date === filterDate : isThisMonth;
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [transactions, filterDate]);

  // Definição de cores por aba
  const tabConfig: Record<Tab, { bg: string, text: string, border: string, icon: string, label: string }> = {
    home: { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: 'fa-house', label: 'Início' },
    extract: { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: 'fa-receipt', label: 'Extrato' },
    calendar: { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100', icon: 'fa-calendar', label: 'Fluxo' },
    analytics: { bg: 'bg-violet-50', text: 'text-violet-600', border: 'border-violet-100', icon: 'fa-chart-pie', label: 'Metas' },
    fixed: { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100', icon: 'fa-clock', label: 'Fixos' },
    settings: { bg: 'bg-slate-100', text: 'text-slate-600', border: 'border-slate-200', icon: 'fa-gear', label: 'Ajustes' }
  };

  const currentTheme = tabConfig[activeTab];

  return (
    <div className={`min-h-screen bg-white flex flex-col font-sans pb-20 transition-colors duration-300`}>

      {activeTab !== 'home' && (
        <SummaryHeader onHand={stats.onHand} projected={stats.projectedTotal} futureExpenses={stats.futureExpenses} />
      )}

      <main className="flex-1 w-full max-w-xl mx-auto px-4 py-6">
        {activeTab === 'home' && (
          <div className="space-y-5 animate-in fade-in duration-300">
            <header className="flex justify-between items-center px-1">
               <div>
                 <h1 className="text-xl font-black tracking-tighter text-slate-800">FINANZA.</h1>
                 <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Executivo Financeiro</p>
               </div>
               <div className="text-slate-300 text-base">
