import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, FinancialStats, Tab } from './types';
import { TransactionForm } from './components/TransactionForm';
import { FinancialCalendar } from './components/FinancialCalendar';
import { SummaryHeader } from './components/SummaryHeader';
import { GeminiAdvisor } from './components/GeminiAdvisor';
import { calculateFinances, formatCurrency, formatDate, getCategoryTotals } from './utils';

const App: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finanza_v6_data');
    return saved ? JSON.parse(saved) : [];
  });
  const [customCategories, setCustomCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('finanza_v6_cats');
    return saved ? JSON.parse(saved) : ['Alimentação', 'Transporte', 'Lazer'];
  });
  const [activeTab, setActiveTab] = useState<Tab>('home');
  const [language, setLanguage] = useState<'pt' | 'en' | 'es' | 'fr'>('pt');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [filterDate, setFilterDate] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('finanza_v6_data', JSON.stringify(transactions));
    localStorage.setItem('finanza_v6_cats', JSON.stringify(customCategories));
  }, [transactions, customCategories]);

  const stats = useMemo(() => calculateFinances(transactions), [transactions]);
  const categoryTotals = useMemo(() => getCategoryTotals(transactions), [transactions]);

  const handleAdd = (t: Transaction) => {
    if (editingTransaction) {
      setTransactions(prev => prev.map(item => item.id === t.id ? t : item));
      setEditingTransaction(null);
    } else {
      setTransactions(prev => [t, ...prev]);
    }
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Excluir este lançamento permanentemente?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const filteredExtract = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    return transactions.filter(t => {
      const d = new Date(t.date + 'T12:00:00');
      const isThisMonth = d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      return filterDate ? t.date === filterDate : isThisMonth;
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [transactions, filterDate]);

  const tabConfig: Record<Tab, { bg: string, text: string, border: string, icon: string, label: string, pastel: string }> = {
    home: { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: 'fa-house', label: 'Início', pastel: 'bg-blue-50/30' },
    extract: { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: 'fa-receipt', label: 'Extrato', pastel: 'bg-emerald-50/30' },
    calendar: { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100', icon: 'fa-calendar', label: 'Fluxo', pastel: 'bg-amber-50/30' },
    analytics: { bg: 'bg-violet-50', text: 'text-violet-600', border: 'border-violet-100', icon: 'fa-chart-pie', label: 'Metas', pastel: 'bg-violet-50/30' },
    fixed: { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100', icon: 'fa-clock', label: 'Fixos', pastel: 'bg-rose-50/30' }
  };

  const currentTheme = tabConfig[activeTab];

  return (
    <div className={`min-h-screen ${currentTheme.pastel} flex flex-col font-sans pb-16 transition-colors duration-500`}>

      {activeTab !== 'home' ? (
        <SummaryHeader 
          onHand={stats.onHand} 
          projected={stats.projectedTotal} 
          futureExpenses={stats.futureExpenses} 
          onOpenSettings={() => setIsSettingsOpen(true)}
        />
      ) : null}

      <main className="flex-1 w-full max-w-xl mx-auto px-4 py-4">
        {activeTab === 'home' && (
          <div className="space-y-4 animate-in fade-in duration-300">
            <header className="flex justify-between items-center px-1">
               <div>
                 <h1 className="text-xl font-black tracking-tighter text-slate-800">FINANZA.</h1>
                 <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Consultoria Pessoal</p>
               </div>
               <button 
                 onClick={() => setIsSettingsOpen(true)}
