        {activeTab === 'fixed' && (
          <div className="space-y-4 animate-in fade-in duration-300">
            <h2 className="text-base font-bold text-slate-700 px-1">Custos Fixos</h2>
            <div className="space-y-2">
              {transactions.filter(t => t.isFixed).map(t => (
                <div key={t.id} className="bg-white p-4 rounded-md border border-slate-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-rose-50 text-rose-300 rounded flex items-center justify-center text-xs">
                      <i className="fa-solid fa-sync"></i>
                    </div>
                    <div>
                      <p className="font-bold text-xs text-slate-700">{t.description}</p>
                      <p className="text-[8px] font-bold text-rose-300 uppercase tracking-tight">Dia {t.fixedDay} • {t.recurrenceMonths === 0 ? 'Permanente' : `${t.recurrenceMonths} meses`}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-bold text-slate-700">{formatCurrency(t.amount)}</p>
                    <button onClick={() => handleDelete(t.id)} className="text-[7px] font-bold text-rose-200 hover:text-rose-500 uppercase tracking-widest">Excluir</button>
                  </div>
                </div>
              ))}
              {transactions.filter(t => t.isFixed).length === 0 && <p className="text-center py-10 text-slate-300 text-[8px] font-bold uppercase tracking-widest">Sem fixos</p>}
            </div>
          </div>
        )}
      </main>

      {/* NAVEGAÇÃO INFERIOR - DESIGN GRUDADO COM DELIMITADORES E NOMES */}
      <nav className="fixed bottom-0 left-0 right-0 h-16 bg-white border-t border-slate-200 flex items-center z-40">
        {(Object.keys(tabConfig) as Tab[]).map((tabId, idx, arr) => {
          const cfg = tabConfig[tabId];
          const isSelected = activeTab === tabId;
          return (
            <button
              key={tabId}
              onClick={() => setActiveTab(tabId)}
              className={`flex-1 h-full flex flex-col items-center justify-center gap-1 transition-all relative ${isSelected ? cfg.bg : 'bg-white opacity-40'} ${idx !== arr.length - 1 ? 'border-r border-slate-100' : ''}`}
            >
              {isSelected && <div className={`absolute top-0 left-0 right-0 h-0.5 ${cfg.text.replace('text', 'bg')}`}></div>}
              <i className={`fa-solid ${cfg.icon} ${isSelected ? cfg.text : 'text-slate-500'} text-sm`}></i>
              <span className={`text-[8px] font-black uppercase tracking-[0.1em] ${isSelected ? cfg.text : 'text-slate-400'}`}>{cfg.label}</span>
            </button>
          );
        })}
      </nav>

      {/* BOTÃO DE ADIÇÃO RÁPIDA (fora da Home) */}
      {activeTab !== 'home' && (
        <button 
          onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }}
          className="fixed bottom-20 right-4 w-12 h-12 bg-slate-800 text-white rounded-md shadow-lg flex items-center justify-center z-40 hover:bg-slate-900 transition-all"
        >
          <i className="fa-solid fa-plus text-lg"></i>
        </button>
      )}

      {/* MODAL DE CONFIGURAÇÕES */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-slate-900/30 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white w-full max-w-sm rounded-md p-6 shadow-2xl border border-slate-100">
              <div className="flex justify-between items-center mb-6 border-b border-slate-50 pb-4">
                 <h2 className="text-base font-bold text-slate-700 tracking-tight">Preferências</h2>
                 <button onClick={() => setIsSettingsOpen(false)} className="text-slate-300 hover:text-slate-500">
                    <i className="fa-solid fa-xmark text-lg"></i>
                 </button>
              </div>

              <div className="space-y-6">
                 <div>
                    <label className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-3 block">Idioma da Interface</label>
                    <div className="grid grid-cols-2 gap-2">
                       {[
                         { code: 'pt', label: 'Português', icon: '🇧🇷' },
                         { code: 'en', label: 'English', icon: '🇺🇸' },
                         { code: 'es', label: 'Español', icon: '🇪🇸' },
                         { code: 'fr', label: 'Français', icon: '🇫🇷' }
                       ].map(lang => (
                         <button 
                           key={lang.code}
                           onClick={() => setLanguage(lang.code as any)}
                           className={`flex items-center justify-between p-3 rounded-md border text-[10px] font-bold transition-all ${language === lang.code ? 'bg-slate-50 border-slate-400 text-slate-800 shadow-sm' : 'bg-white border-slate-100 text-slate-400 hover:bg-slate-50'}`}
                         >
                           <span>{lang.label}</span>
                           <span>{lang.icon}</span>
                         </button>
                       ))}
                    </div>
                 </div>

                 <div className="pt-4 border-t border-slate-50">
                    <button 
                      onClick={() => { if(window.confirm('Excluir todos os dados salvos?')) { setTransactions([]); localStorage.clear(); setIsSettingsOpen(false); } }}
                      className="w-full text-[9px] font-bold text-rose-400 uppercase tracking-widest py-3 border border-rose-100 rounded-md hover:bg-rose-50 transition-all"
                    >
                      Resetar Aplicação
                    </button>
                 </div>

                 <div className="text-center pt-2">
                    <p className="text-[7px] text-slate-300 font-bold tracking-[0.2em] uppercase">Versão 7.0 Gold Edition</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL DE FORMULÁRIO */}
      {isFormOpen && (
        <TransactionForm 
          onAdd={handleAdd} 
          onClose={() => setIsFormOpen(false)} 
          initialData={editingTransaction}
          customCategories={customCategories}
          onAddCategory={(c) => setCustomCategories(prev => [...prev, c])}
        />
      )}
    </div>
  );
};

export default App;

