    home: { icon: 'fa-house', label: 'Início' },
    extract: { icon: 'fa-receipt', label: 'Extrato' },
    calendar: { icon: 'fa-calendar', label: 'Fluxo' },
    analytics: { icon: 'fa-chart-pie', label: 'Metas' },
    fixed: { icon: 'fa-clock', label: 'Fixos' }
  };

