                    <div key={w.id} className="bg-white p-6 rounded-[32px] border-2 border-slate-100 shadow-sm space-y-4">
                       <div className="flex justify-between items-start">
                          <div>
                             <h3 className="text-sm font-black text-slate-800">{w.title}</h3>
